CREATE TABLE `books` (
  `book_id` int NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `author` varchar(255) DEFAULT 'Unknown Author',
  `genre` varchar(255) DEFAULT NULL,
  `number_of_copies` int DEFAULT NULL,
