  `summary` text,
  `characters` text,
  `pages` int DEFAULT NULL,
  `order_price` decimal(6,2) DEFAULT NULL,
  `rating` decimal(3,2) DEFAULT NULL,
  PRIMARY KEY (`book_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
